(async () => {
  const pages = figma.root.children;
  const result = [];
  for (const page of pages) {
    result.push({ id: page.id, name: page.name });
  }

  // Find "00 · Start Here" page
  const startHerePage = pages.find(p => p.name.includes("00"));
  let startHereText = [];
  if (startHerePage) {
    await startHerePage.loadAsync();
    const textNodes = startHerePage.findAll(node => node.type === "TEXT");
    for (const t of textNodes) {
      startHereText.push({ name: t.name, characters: t.characters });
    }
  }

  return { pages: result, startHereText };
})()

(async () => {
  const pages = figma.root.children;

  async function inspectPage(pageName) {
    const page = pages.find(p => p.name.includes(pageName));
    if (!page) return null;
    await page.loadAsync();

    const nodes = page.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type,
      width: c.width,
      height: c.height,
      children: c.children ? c.children.map(ch => ({ id: ch.id, name: ch.name, type: ch.type })) : []
    }));
    return nodes;
  }

  const foundations = await inspectPage("01");
  const components = await inspectPage("02");
  const media = await inspectPage("04");

  return { foundations, components, media };
})()

(async () => {
  async function getChildrenOf(parentId) {
    const node = await figma.getNodeByIdAsync(parentId);
    if (!node || !node.children) return [];
    return node.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type,
      width: c.width,
      height: c.height
    }));
  }

  // Brand children (2:5)
  const brand = await getChildrenOf("2:5");
  // Product photos children (2:11)
  const products = await getChildrenOf("2:11");
  // Illustrations (2:29)
  const illustrations = await getChildrenOf("2:29");
  // Icons (2:53)
  const icons = await getChildrenOf("2:53");

  // Also get the colors / properties of foundations brand primary color to be exact
  const brandPrimaryNode = await figma.getNodeByIdAsync("3:6");
  let brandPrimaryColor = null;
  if (brandPrimaryNode && brandPrimaryNode.fills) {
    brandPrimaryColor = brandPrimaryNode.fills;
  }

  return { brand, products, illustrations, icons, brandPrimaryColor };
})()

(async () => {
  const getSubNodes = async (gridId) => {
    const node = await figma.getNodeByIdAsync(gridId);
    if (!node || !node.children) return [];
    return node.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type,
      width: c.width,
      height: c.height
    }));
  };

  const brandGrid = await getSubNodes("2:7");
  const productsGrid = await getSubNodes("2:13");
  const illustrationsGrid = await getSubNodes("2:31");
  const iconsGrid = await getSubNodes("2:55");

  // Let's also find the fills on "3:6" brand primary by inspecting the children or finding the colored node inside it.
  const brandPrimaryFrame = await figma.getNodeByIdAsync("3:6");
  let colorDetails = null;
  if (brandPrimaryFrame) {
    // If it's a frame, let's find if it has fills or contains a rectangle with fills
    colorDetails = {
      fills: brandPrimaryFrame.fills,
      name: brandPrimaryFrame.name
    };
    if (brandPrimaryFrame.children) {
      colorDetails.children = brandPrimaryFrame.children.map(c => ({
        id: c.id,
        name: c.name,
        fills: c.fills,
        type: c.type
      }));
    }
  }

  return { brandGrid, productsGrid, illustrationsGrid, iconsGrid, colorDetails };
})()

(async () => {
  const getSubNodeNames = async (parentId) => {
    const parent = await figma.getNodeByIdAsync(parentId);
    if (!parent || !parent.children) return [];

    // Find nested children inside tiles
    const tilesData = [];
    for (const tile of parent.children) {
      if (tile.type === "FRAME" && tile.children) {
        const namedChildren = tile.children.map(c => ({
          id: c.id,
          name: c.name,
          type: c.type
        }));
        tilesData.push({ tileId: tile.id, tileName: tile.name, children: namedChildren });
      }
    }
    return tilesData;
  };

  const brandTiles = await getSubNodeNames("2:7");
  const productsTiles = await getSubNodeNames("2:13");
  const illustrationsTiles = await getSubNodeNames("2:31");
  const iconsTiles = await getSubNodeNames("2:55");

  return { brandTiles, productsTiles, illustrationsTiles, iconsTiles };
})()

