(async () => {
  const shellFrame = await figma.getNodeByIdAsync("3:44");
  if (!shellFrame) return null;
  const statusBars = [];
  const homeIndicators = [];

  for (const child of shellFrame.children) {
    if (child.name === "Status Bar" || child.name === "Home Indicator") {
      const subChildren = child.children ? child.children.map(c => ({ id: c.id, name: c.name, type: c.type, width: c.width, height: c.height })) : [];
      if (child.name === "Status Bar") statusBars.push({ id: child.id, name: child.name, width: child.width, height: child.height, subChildren });
      if (child.name === "Home Indicator") homeIndicators.push({ id: child.id, name: child.name, width: child.width, height: child.height, subChildren });
    }
  }
  return { statusBars, homeIndicators };
})()

