(async () => {
  // Let's inspect the Prototype reactions API.
  // Standard Figma Plugin API for setting reactions:
  // node.reactions = [ { trigger: { type: 'ON_CLICK' }, actions: [ { type: 'NODE', destinationId: '...', navigation: 'NAVIGATE' } ] } ]
  // For timed transitions (AFTER_TIMEOUT):
  // { trigger: { type: 'AFTER_TIMEOUT', timeout: 2000 }, actions: [ { type: 'NODE', destinationId: '...', navigation: 'NAVIGATE' } ] }

  const workspacePage = figma.root.children.find(p => p.name.includes("03 · Workspace"));
  const getFrame = (name) => workspacePage.children.find(c => c.name === name);

  const f01 = getFrame("01_Splash");
  const f02 = getFrame("02_Welcome");
  const f03 = getFrame("03_Name");
  const f04 = getFrame("04_Home");
  const f05 = getFrame("05_Product_Quinoa");
  const f06 = getFrame("06_Basket");
  const f07 = getFrame("07_Checkout_Delivery");
  const f08 = getFrame("08_Checkout_Card");
  const f09 = getFrame("09_Order_Complete");
  const f10 = getFrame("10_Track_Order");

  const findNodeByName = (root, name) => {
    if (!root) return null;
    if (root.name === name) return root;
    if (root.children) {
      for (const child of root.children) {
        const res = findNodeByName(child, name);
        if (res) return res;
      }
    }
    return null;
  };

  // 1. 01_Splash -> auto -> 02_Welcome
  if (f01 && f02) {
    f01.reactions = [{
      trigger: { type: 'AFTER_TIMEOUT', timeout: 1.5 },
      actions: [{ type: 'NODE', destinationId: f02.id, navigation: 'NAVIGATE', transition: null }]
    }];
  }

  // Helper to safely set on_click reaction
  const setClickReaction = (fromNode, toNode) => {
    if (fromNode && toNode) {
      fromNode.reactions = [{
        trigger: { type: 'ON_CLICK' },
        actions: [{ type: 'NODE', destinationId: toNode.id, navigation: 'NAVIGATE', transition: null }]
      }];
    }
  };

  // 2. 02_Welcome -> Let’s Continue (Button) -> 03_Name
  setClickReaction(findNodeByName(f02, "Button"), f03);

  // 3. 03_Name -> Start Ordering (Button) -> 04_Home
  setClickReaction(findNodeByName(f03, "Button"), f04);

  // 4. 04_Home:
  // Quinoa fruit salad -> 05_Product_Quinoa
  setClickReaction(findNodeByName(f04, "Card_Quinoa fruit salad"), f05);
  // My basket -> 06_Basket
  setClickReaction(findNodeByName(f04, "My basket entry"), f06);

  // 5. 05_Product_Quinoa:
  // Go back -> 04_Home
  setClickReaction(findNodeByName(f05, "Go back"), f04);
  // Add to basket -> 06_Basket
  setClickReaction(findNodeByName(f05, "Button"), f06);

  // 6. 06_Basket:
  // Go back -> 04_Home
  setClickReaction(findNodeByName(f06, "Go back"), f04);
  // Checkout -> 07_Checkout_Delivery
  setClickReaction(findNodeByName(f06, "Button"), f07);

  // 7. 07_Checkout_Delivery:
  // close -> 06_Basket
  setClickReaction(findNodeByName(f07, "close"), f06);
  // Pay with card -> 08_Checkout_Card
  setClickReaction(findNodeByName(f07, "Pay with card"), f08);
  // Pay on delivery -> 09_Order_Complete
  setClickReaction(findNodeByName(f07, "Pay on delivery"), f09);

  // 8. 08_Checkout_Card:
  // close -> 06_Basket
  setClickReaction(findNodeByName(f08, "close"), f06);
  // Complete Order -> 09_Order_Complete
  setClickReaction(findNodeByName(f08, "Complete Order"), f09);

  // 9. 09_Order_Complete:
