  congratsText.fontName = { family: "Nunito", style: "Bold" };
  congratsText.fontSize = 24;
  congratsText.fills = [{ type: 'SOLID', color: brandDarkColor }];
  congratsText.x = (375 - 200) / 2;
  congratsText.y = 360;
  f09.appendChild(congratsText);

  const subText = figma.createText();
  subText.characters = "Your order has been taken and is being attended to";
  subText.fontName = { family: "Nunito", style: "Regular" };
  subText.fontSize = 16;
  subText.fills = [{ type: 'SOLID', color: { r: 0.35, g: 0.35, b: 0.35 } }];
  subText.textAlignHorizontal = "CENTER";
  subText.resize(280, 48);
  subText.x = (375 - 280) / 2;
  subText.y = 405;
  f09.appendChild(subText);

  if (buttonOrig) {
    const trackBtn = buttonOrig.createInstance();
    trackBtn.x = 24;
    trackBtn.y = 520;
    trackBtn.name = "Track order";
    const btnText = trackBtn.findOne(n => n.type === "TEXT");
    if (btnText) {
      btnText.characters = "Track order";
    }
    f09.appendChild(trackBtn);
  }

  const continueBtn = figma.createFrame();
  continueBtn.name = "Continue shopping";
  continueBtn.resize(327, 56);
  continueBtn.x = 24;
  continueBtn.y = 596;
  continueBtn.cornerRadius = 10;
  continueBtn.strokes = [{ type: 'SOLID', color: brandPrimaryColor }];
  continueBtn.strokeWeight = 1;
  continueBtn.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];

  const contText = figma.createText();
  contText.characters = "Continue shopping";
  contText.fontName = { family: "Nunito", style: "Bold" };
  contText.fontSize = 16;
  contText.fills = [{ type: 'SOLID', color: brandPrimaryColor }];
  contText.x = 94;
  contText.y = 17;
  continueBtn.appendChild(contText);

  f09.appendChild(continueBtn);

  // --- 10_Track_Order ---
  const f10 = createFrame("10_Track_Order", 3825, 0);
  f10.fills = [{ type: 'SOLID', color: brandPrimaryColor }];
  await addShell(f10);

  if (iconBackOrig) {
    const goBackBtn = figma.createFrame();
    goBackBtn.name = "Go back";
    goBackBtn.resize(80, 32);
    goBackBtn.x = 24;
    goBackBtn.y = 56;
    goBackBtn.cornerRadius = 16;
    goBackBtn.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];

    const backIcon = iconBackOrig.createInstance();
    backIcon.x = 8;
    backIcon.y = 4;
    goBackBtn.appendChild(backIcon);

    const backText = figma.createText();
    backText.characters = "Go back";
    backText.fontName = { family: "Nunito", style: "SemiBold" };
    backText.fontSize = 12;
    backText.fills = [{ type: 'SOLID', color: brandDarkColor }];
    backText.x = 28;
    backText.y = 8;
    goBackBtn.appendChild(backText);

    f10.appendChild(goBackBtn);
  }

  const trackTitle = figma.createText();
  trackTitle.characters = "Delivery Status";
  trackTitle.fontName = { family: "Nunito", style: "Bold" };
  trackTitle.fontSize = 24;
  trackTitle.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
  trackTitle.x = 120;
  trackTitle.y = 56;
  f10.appendChild(trackTitle);

  const mapOrig = await getOrig("2:50");
  if (mapOrig) {
    const mapContainer = figma.createFrame();
    mapContainer.name = "Map Container";
    mapContainer.resize(375, 220);
    mapContainer.x = 0;
    mapContainer.y = 108;
    mapContainer.fills = [];

    const map = mapOrig.createInstance();
    map.x = 0;
    map.y = 0;
    mapContainer.appendChild(map);

    f10.appendChild(mapContainer);
  }

  const stepsSheet = figma.createFrame();
  stepsSheet.name = "Steps Sheet";
  stepsSheet.resize(375, 450);
  stepsSheet.x = 0;
  stepsSheet.y = 328;
  stepsSheet.cornerRadius = 24;
  stepsSheet.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];

  const iconDoneOrig = await getOrig("2:140");
  const stepTakenOrig = await getOrig("2:41");
  const stepPreparedOrig = await getOrig("2:44");
  const stepDeliveringOrig = await getOrig("2:47");
  const iconCallOrig = await getOrig("2:134");

  const stepsData = [
    { name: "Order Taken", status: "done", photoOrig: stepTakenOrig, subtitle: null },
    { name: "Order Is Being Prepared", status: "done", photoOrig: stepPreparedOrig, subtitle: null },
    { name: "Order Is Being Delivered", status: "current", photoOrig: stepDeliveringOrig, subtitle: "Your delivery agent is coming" },
    { name: "Order Received", status: "pending", photoOrig: null, subtitle: null }
  ];

  let stepY = 32;
  for (let i = 0; i < stepsData.length; i++) {
    const st = stepsData[i];
    const stepRow = figma.createFrame();
    stepRow.name = `StepRow_${st.name}`;
    stepRow.resize(327, 70);
    stepRow.x = 24;
    stepRow.y = stepY;
    stepRow.fills = [];

    if (st.photoOrig) {
      const img = st.photoOrig.createInstance();
      img.resize(48, 48);
      img.x = 0;
      img.y = 0;
      stepRow.appendChild(img);
    } else {
      const pendingCircle = figma.createEllipse();
      pendingCircle.resize(48, 48);
      pendingCircle.x = 0;
      pendingCircle.y = 0;
      pendingCircle.fills = [{ type: 'SOLID', color: { r: 0.93, g: 0.93, b: 0.93 } }];
      stepRow.appendChild(pendingCircle);
    }

    const sTitle = figma.createText();
    sTitle.characters = st.name;
    sTitle.fontName = { family: "Nunito", style: st.status === "pending" ? "Regular" : "Bold" };
    sTitle.fontSize = 15;
    sTitle.fills = [{ type: 'SOLID', color: st.status === "pending" ? { r: 0.6, g: 0.6, b: 0.6 } : brandDarkColor }];
    sTitle.x = 64;
    sTitle.y = st.subtitle ? 4 : 14;
    stepRow.appendChild(sTitle);

    if (st.subtitle) {
      const sSub = figma.createText();
      sSub.characters = st.subtitle;
      sSub.fontName = { family: "Nunito", style: "Regular" };
      sSub.fontSize = 12;
      sSub.fills = [{ type: 'SOLID', color: { r: 0.5, g: 0.5, b: 0.5 } }];
      sSub.x = 64;
      sSub.y = 26;
      stepRow.appendChild(sSub);
    }

    if (st.status === "done" && iconDoneOrig) {
      const doneCheck = iconDoneOrig.createInstance();
      doneCheck.x = 295;
      doneCheck.y = 12;
      stepRow.appendChild(doneCheck);
    } else if (st.status === "current" && iconCallOrig) {
      const callBtn = iconCallOrig.createInstance();
      callBtn.x = 285;
      callBtn.y = 8;
      callBtn.name = "call the delivery agent";
      stepRow.appendChild(callBtn);
    }

    stepsSheet.appendChild(stepRow);
    stepY += 82;
  }

  f10.appendChild(stepsSheet);

  // Set prototype reactions
  f01.reactions = [{
    trigger: { type: 'AFTER_TIMEOUT', timeout: 1.5 },
    actions: [{ type: 'NODE', destinationId: f02.id, navigation: 'NAVIGATE', transition: null }]
  }];

  const findNodeByName = (root, name) => {
    if (!root) return null;
    if (root.name === name) return root;
    if (root.children) {
      for (const child of root.children) {
        const res = findNodeByName(child, name);
        if (res) return res;
      }
    }
    return null;
  };

  const setClickReaction = (fromNode, toNode) => {
    if (fromNode && toNode) {
      fromNode.reactions = [{
        trigger: { type: 'ON_CLICK' },
        actions: [{ type: 'NODE', destinationId: toNode.id, navigation: 'NAVIGATE', transition: null }]
      }];
    }
  };

  setClickReaction(findNodeByName(f02, "Button"), f03);
  setClickReaction(findNodeByName(f03, "Button"), f04);
  setClickReaction(findNodeByName(f04, "Card_Quinoa fruit salad"), f05);
  setClickReaction(findNodeByName(f04, "My basket entry"), f06);
  setClickReaction(findNodeByName(f05, "Go back"), f04);
  setClickReaction(findNodeByName(f05, "Button"), f06);
  setClickReaction(findNodeByName(f06, "Go back"), f04);
  setClickReaction(findNodeByName(f06, "Button"), f07);
  setClickReaction(findNodeByName(f07, "close"), f06);
  setClickReaction(findNodeByName(f07, "Pay with card"), f08);
  setClickReaction(findNodeByName(f07, "Pay on delivery"), f09);
  setClickReaction(findNodeByName(f08, "close"), f06);
  setClickReaction(findNodeByName(f08, "Complete Order"), f09);
  setClickReaction(findNodeByName(f09, "Track order"), f10);
  setClickReaction(findNodeByName(f09, "Continue shopping"), f04);
  setClickReaction(findNodeByName(f10, "Go back"), f04);

  return "All 10 frames and reactions created cleanly in a single script";
})()

(async () => {
  const workspacePage = figma.root.children.find(p => p.name.includes("03 · Workspace"));
  if (!workspacePage) return [];
  return workspacePage.children.map(c => ({
    id: c.id,
    name: c.name,
    type: c.type,
    x: c.x,
    y: c.y,
    width: c.width,
    height: c.height
  }));
})()

(async () => {
  const workspacePage = figma.root.children.find(p => p.name.includes("03 · Workspace"));
  if (!workspacePage) return "Workspace not found";

  // Keep only nodes with IDs starting with "11:" or are the latest ones
  for (const child of workspacePage.children) {
    if (!child.id.startsWith("11:")) {
      child.remove();
    }
  }

  return workspacePage.children.map(c => ({ id: c.id, name: c.name }));
})()
